     1→/**
     2→ * Message Sender Service
     3→ *
     4→ * Handles sending text and image messages via WhatsApp Cloud API
     5→ * Integrates with WhatsAppApiClient and MessageService
     6→ */
     7→
     8→import WhatsAppApiClient from './WhatsAppApiClient.js';
     9→import WhatsAppLine from '../../models/sequelize/WhatsAppLine.js';
    10→import Message from '../../models/sequelize/Message.js';
    11→import Lead from '../../models/sequelize/Lead.js';
    12→import User from '../../models/sequelize/User.js';
    13→import { AppError } from '../../middleware/errorHandler.js';
    14→import SocketService  from '../SocketService.js';
    15→
    16→/**
    17→ * MessageSender Class
    18→ */
    19→class MessageSender {
    20→  /**
    21→   * Send text message
    22→   *
    23→   * @param {Object} params - Message parameters
    24→   * @param {number} params.lineId - WhatsApp line ID
    25→   * @param {string} params.phoneNumber - Recipient phone number (E.164)
    26→   * @param {string} params.messageContent - Message text
    27→   * @param {number} params.userId - Sending user ID
    28→   * @param {number} params.leadId - Lead ID (optional)
    29→   * @returns {Promise<Object>} Sent message record
    30→   */
    31→  static async sendTextMessage({ lineId, phoneNumber, messageContent, userId, leadId }) {
    32→    try {
    33→      // Get WhatsApp line with credentials
    34→      const line = await WhatsAppLine.findByPk(lineId);
    35→
    36→      if (!line) {
    37→        throw new AppError('WhatsApp line not found', 404);
    38→      }
    39→
    40→      if (!line.is_active) {
    41→        throw new AppError('WhatsApp line is not active', 400);
    42→      }
    43→
    44→      // Create WhatsApp API client
    45→      console.log('[MessageSender] Creating WhatsApp API client with:', {
    46→        phoneNumberId: line.phone_number_id,
    47→        accessTokenLength: line.access_token?.length,
    48→        accessTokenStart: line.access_token?.substring(0, 20),
    49→        businessAccountId: line.business_account_id
    50→      });
    51→
    52→      const apiClient = new WhatsAppApiClient({
    53→        phoneNumberId: line.phone_number_id,
    54→        accessToken: line.access_token?.trim(),
    55→        businessAccountId: line.business_account_id
    56→      });
    57→
    58→      // Send message via WhatsApp API
    59→      const apiResponse = await apiClient.sendTextMessage(
    60→        phoneNumber,
    61→        messageContent,
    62→        { previewUrl: true }
    63→      );
    64→
    65→      // Get or create lead
    66→      let lead = leadId ? await Lead.findByPk(leadId) : null;
    67→
    68→      if (!lead) {
    69→        lead = await Lead.findOne({ where: { phone_number: phoneNumber } });
    70→      }
    71→
    72→      // Save message to database
    73→      const message = await Message.create({
    74→        line_id: lineId,
    75→        lead_id: lead?.id || null,
    76→        user_id: userId,
    77→        phone_number: phoneNumber,
    78→        message_content: messageContent,
    79→        message_type: 'text',
    80→        direction: 'outgoing',
    81→        status: 'sent',
    82→        meta_message_id: apiResponse.messageId,
    83→        created_at: new Date()
    84→      });
    85→
    86→      // Load user relation for socket broadcast
    87→      const messageWithRelations = await Message.findByPk(message.id, {
    88→        include: [
    89→          { model: Lead, as: 'lead' },
    90→          { model: User, as: 'sender', attributes: ['id', 'name', 'email'] }
    91→        ]
    92→      });
    93→
    94→      // Emit message:sent event via Socket.io
    95→      SocketService.emitToLine(lineId, 'message:sent', {
    96→        message: messageWithRelations,
    97→        conversationId: `${phoneNumber}_${lineId}`
    98→      });
    99→
   100→      return messageWithRelations;
   101→    } catch (error) {
   102→      console.error('Error sending text message:', error);
   103→
   104→      // If API error, save failed message to DB
   105→      if (error.statusCode && error.statusCode >= 400) {
   106→        await Message.create({
   107→          line_id: lineId,
   108→          lead_id: leadId || null,
   109→          user_id: userId,
   110→          phone_number: phoneNumber,
   111→          message_content: messageContent,
   112→          message_type: 'text',
   113→          direction: 'outgoing',
   114→          status: 'failed',
   115→          created_at: new Date()
   116→        });
   117→      }
   118→
   119→      throw error;
   120→    }
   121→  }
