/**
 * Message Sender Service
 *
 * Handles sending text and image messages via WhatsApp Cloud API
 * Integrates with WhatsAppApiClient and MessageService
 */

import WhatsAppApiClient from './WhatsAppApiClient.js';
import WhatsAppLine from '../../models/sequelize/WhatsAppLine.js';
import Message from '../../models/sequelize/Message.js';
import Lead from '../../models/sequelize/Lead.js';
import User from '../../models/sequelize/User.js';
import { AppError } from '../../middleware/errorHandler.js';
import SocketService  from '../SocketService.js';

/**
 * MessageSender Class
 */
class MessageSender {
  /**
   * Send text message
   *
   * @param {Object} params - Message parameters
   * @param {number} params.lineId - WhatsApp line ID
   * @param {string} params.phoneNumber - Recipient phone number (E.164)
   * @param {string} params.messageContent - Message text
   * @param {number} params.userId - Sending user ID
   * @param {number} params.leadId - Lead ID (optional)
   * @returns {Promise<Object>} Sent message record
   */
  static async sendTextMessage({ lineId, phoneNumber, messageContent, userId, leadId }) {
    try {
      // Get WhatsApp line with credentials
      const line = await WhatsAppLine.findByPk(lineId);

      if (!line) {
        throw new AppError('WhatsApp line not found', 404);
      }

      if (!line.is_active) {
        throw new AppError('WhatsApp line is not active', 400);
      }

      // Create WhatsApp API client
      console.log('[MessageSender] Creating WhatsApp API client with:', {
        phoneNumberId: line.phone_number_id,
        accessTokenLength: line.access_token?.length,
        accessTokenStart: line.access_token?.substring(0, 20),
        businessAccountId: line.business_account_id
      });

      const apiClient = new WhatsAppApiClient({
        phoneNumberId: line.phone_number_id,
        accessToken: line.access_token?.trim(),
        businessAccountId: line.business_account_id
      });

      // Send message via WhatsApp API
      const apiResponse = await apiClient.sendTextMessage(
        phoneNumber,
        messageContent,
        { previewUrl: true }
      );

      // Get or create lead
      let lead = leadId ? await Lead.findByPk(leadId) : null;

      if (!lead) {
        lead = await Lead.findOne({ where: { phone_number: phoneNumber } });
      }

      // Save message to database
      const message = await Message.create({
        line_id: lineId,
        lead_id: lead?.id || null,
        user_id: userId,
        phone_number: phoneNumber,
        message_content: messageContent,
        message_type: 'text',
        direction: 'outgoing',
        status: 'sent',
        meta_message_id: apiResponse.messageId,
        created_at: new Date()
      });

      // Load user relation for socket broadcast
      const messageWithRelations = await Message.findByPk(message.id, {
        include: [
          { model: Lead, as: 'lead' },
          { model: User, as: 'sender', attributes: ['id', 'name', 'email'] }
        ]
      });

      // Emit message:sent event via Socket.io
      SocketService.emitToLine(lineId, 'message:sent', {
        message: messageWithRelations,
        conversationId: `${phoneNumber}_${lineId}`
      });

      return messageWithRelations;
    } catch (error) {
      console.error('Error sending text message:', error);

      // If API error, save failed message to DB
      if (error.statusCode && error.statusCode >= 400) {
        await Message.create({
          line_id: lineId,
          lead_id: leadId || null,
          user_id: userId,
          phone_number: phoneNumber,
          message_content: messageContent,
          message_type: 'text',
          direction: 'outgoing',
          status: 'failed',
          created_at: new Date()
        });
      }

      throw error;
    }
  }

  /**
   * Send image message
   *
   * @param {Object} params - Message parameters
   * @param {number} params.lineId - WhatsApp line ID
   * @param {string} params.phoneNumber - Recipient phone number (E.164)
   * @param {string} params.imageUrl - Public image URL or media ID
   * @param {string} params.caption - Image caption (optional)
   * @param {number} params.userId - Sending user ID
   * @param {number} params.leadId - Lead ID (optional)
   * @param {boolean} params.isMediaId - True if imageUrl is media ID
   * @returns {Promise<Object>} Sent message record
   */
  static async sendImageMessage({
    lineId,
    phoneNumber,
    imageUrl,
    uploadUrl,
    caption,
    userId,
    leadId,
    isMediaId = false
  }) {
    try {
      // Get WhatsApp line with credentials
      const line = await WhatsAppLine.findByPk(lineId);

      if (!line) {
        throw new AppError('WhatsApp line not found', 404);
      }

      if (!line.is_active) {
        throw new AppError('WhatsApp line is not active', 400);
      }

      // Create WhatsApp API client
      const apiClient = new WhatsAppApiClient({
        phoneNumberId: line.phone_number_id,
        accessToken: line.access_token,
        businessAccountId: line.business_account_id
      });

      // Send image via WhatsApp API
      const apiResponse = await apiClient.sendImageMessage(
        phoneNumber,
        imageUrl,
        { caption, isMediaId }
      );

      // Get or create lead
      let lead = leadId ? await Lead.findByPk(leadId) : null;

      if (!lead) {
        lead = await Lead.findOne({ where: { phone_number: phoneNumber } });
      }

      // Save message to database
      const message = await Message.create({
        line_id: lineId,
        lead_id: lead?.id || null,
        user_id: userId,
        phone_number: phoneNumber,
        message_content: caption || '[Image]',
        message_type: 'image',
        direction: 'outgoing',
        status: 'sent',
        file_url: uploadUrl,
        meta_message_id: apiResponse.messageId,
        created_at: new Date()
      });

      // Load relations for socket broadcast
      const messageWithRelations = await Message.findByPk(message.id, {
        include: [
          { model: Lead, as: 'lead' },
          { model: User, as: 'sender', attributes: ['id', 'name', 'email'] }
        ]
      });

      // Emit message:sent event via Socket.io
      SocketService.emitToLine(lineId, 'message:sent', {
        message: messageWithRelations,
        conversationId: `${phoneNumber}_${lineId}`
      });

      return messageWithRelations;
    } catch (error) {
      console.error('Error sending image message:', error);

      // If API error, save failed message to DB
      if (error.statusCode && error.statusCode >= 400) {
        await Message.create({
          line_id: lineId,
          lead_id: leadId || null,
          user_id: userId,
          phone_number: phoneNumber,
          message_content: caption || '[Image]',
          message_type: 'image',
          direction: 'outgoing',
          status: 'failed',
          file_url: imageUrl,
          created_at: new Date()
        });
      }

      throw error;
    }
  }

  /**
   * Send document message
   *
   * @param {Object} params - Message parameters
   * @param {number} params.lineId - WhatsApp line ID
   * @param {string} params.phoneNumber - Recipient phone number (E.164)
   * @param {string} params.documentUrl - Public document URL or media ID
   * @param {string} params.uploadUrl - URL for storage
   * @param {string} params.caption - Document caption (optional)
   * @param {string} params.filename - Document filename
   * @param {number} params.userId - Sending user ID
   * @param {number} params.leadId - Lead ID (optional)
   * @param {boolean} params.isMediaId - True if documentUrl is media ID
   * @returns {Promise<Object>} Sent message record
   */
  static async sendDocumentMessage({
    lineId,
    phoneNumber,
    documentUrl,
    uploadUrl,
    caption,
    filename,
    userId,
    leadId,
    isMediaId = false
  }) {
    try {
      // Get WhatsApp line with credentials
      const line = await WhatsAppLine.findByPk(lineId);

      if (!line) {
        throw new AppError('WhatsApp line not found', 404);
      }

      if (!line.is_active) {
        throw new AppError('WhatsApp line is not active', 400);
      }

      // Create WhatsApp API client
      const apiClient = new WhatsAppApiClient({
        phoneNumberId: line.phone_number_id,
        accessToken: line.access_token,
        businessAccountId: line.business_account_id
      });

      // Send document via WhatsApp API
      const apiResponse = await apiClient.sendDocumentMessage(
        phoneNumber,
        documentUrl,
        { caption, filename, isMediaId }
      );

      // Get or create lead
      let lead = leadId ? await Lead.findByPk(leadId) : null;

      if (!lead) {
        lead = await Lead.findOne({ where: { phone_number: phoneNumber } });
      }

      // Save message to database
      const message = await Message.create({
        line_id: lineId,
        lead_id: lead?.id || null,
        user_id: userId,
        phone_number: phoneNumber,
        message_content: caption || `[Documento: ${filename}]`,
        message_type: 'document',
        direction: 'outgoing',
        status: 'sent',
        file_url: uploadUrl,
        meta_message_id: apiResponse.messageId,
        created_at: new Date()
      });

      // Load relations for socket broadcast
      const messageWithRelations = await Message.findByPk(message.id, {
        include: [
          { model: Lead, as: 'lead' },
          { model: User, as: 'sender', attributes: ['id', 'name', 'email'] }
        ]
      });

      // Emit message:sent event via Socket.io
      SocketService.emitToLine(lineId, 'message:sent', {
        message: messageWithRelations,
        conversationId: `${phoneNumber}_${lineId}`
      });

      return messageWithRelations;
    } catch (error) {
      console.error('Error sending document message:', error);

      // If API error, save failed message to DB
      if (error.statusCode && error.statusCode >= 400) {
        await Message.create({
          line_id: lineId,
          lead_id: leadId || null,
          user_id: userId,
          phone_number: phoneNumber,
          message_content: caption || `[Documento: ${filename}]`,
          message_type: 'document',
          direction: 'outgoing',
          status: 'failed',
          file_url: uploadUrl,
          created_at: new Date()
        });
      }

      throw error;
    }
  }

  /**
   * Send audio message
   *
   * @param {Object} params - Message parameters
   * @param {number} params.lineId - WhatsApp line ID
   * @param {string} params.phoneNumber - Recipient phone number (E.164)
   * @param {string} params.audioUrl - Public audio URL or media ID
   * @param {string} params.uploadUrl - URL for storage
   * @param {number} params.userId - Sending user ID
   * @param {number} params.leadId - Lead ID (optional)
   * @param {boolean} params.isMediaId - True if audioUrl is media ID
   * @returns {Promise<Object>} Sent message record
   */
  static async sendAudioMessage({
    lineId,
    phoneNumber,
    audioUrl,
    uploadUrl,
    userId,
    leadId,
    isMediaId = false
  }) {
    try {
      // Get WhatsApp line with credentials
      const line = await WhatsAppLine.findByPk(lineId);

      if (!line) {
        throw new AppError('WhatsApp line not found', 404);
      }

      if (!line.is_active) {
        throw new AppError('WhatsApp line is not active', 400);
      }

      // Create WhatsApp API client
      const apiClient = new WhatsAppApiClient({
        phoneNumberId: line.phone_number_id,
        accessToken: line.access_token,
        businessAccountId: line.business_account_id
      });

      // Send audio via WhatsApp API
      // If isMediaId is true, audioUrl is actually a media ID
      // Otherwise, ensure the URL is absolute
      let finalAudioUrl = audioUrl;
      let useMediaId = isMediaId;

      // If audioUrl looks like a media ID (numeric), use it as media ID
      if (!useMediaId && /^\d+$/.test(audioUrl)) {
        useMediaId = true;
      }

      const apiResponse = await apiClient.sendAudioMessage(
        phoneNumber,
        finalAudioUrl,
        { isMediaId: useMediaId }
      );

      // Get or create lead
      let lead = leadId ? await Lead.findByPk(leadId) : null;

      if (!lead) {
        lead = await Lead.findOne({ where: { phone_number: phoneNumber } });
      }

      // Save message to database
      const message = await Message.create({
        line_id: lineId,
        lead_id: lead?.id || null,
        user_id: userId,
        phone_number: phoneNumber,
        message_content: '[Audio]',
        message_type: 'audio',
        direction: 'outgoing',
        status: 'sent',
        file_url: uploadUrl,
        meta_message_id: apiResponse.messageId,
        created_at: new Date()
      });

      // Load relations for socket broadcast
      const messageWithRelations = await Message.findByPk(message.id, {
        include: [
          { model: Lead, as: 'lead' },
          { model: User, as: 'sender', attributes: ['id', 'name', 'email'] }
        ]
      });

      // Emit message:sent event via Socket.io
      SocketService.emitToLine(lineId, 'message:sent', {
        message: messageWithRelations,
        conversationId: `${phoneNumber}_${lineId}`
      });

      return messageWithRelations;
    } catch (error) {
      console.error('Error sending audio message:', error);

      // If API error, save failed message to DB
      if (error.statusCode && error.statusCode >= 400) {
        await Message.create({
          line_id: lineId,
          lead_id: leadId || null,
          user_id: userId,
          phone_number: phoneNumber,
          message_content: '[Audio]',
          message_type: 'audio',
          direction: 'outgoing',
          status: 'failed',
          file_url: uploadUrl,
          created_at: new Date()
        });
      }

      throw error;
    }
  }

  /**
   * Send video message
   *
   * @param {Object} params - Message parameters
   * @param {number} params.lineId - WhatsApp line ID
   * @param {string} params.phoneNumber - Recipient phone number (E.164)
   * @param {string} params.videoUrl - Public video URL or media ID
   * @param {string} params.uploadUrl - URL for storage
   * @param {string} params.caption - Video caption (optional)
   * @param {number} params.userId - Sending user ID
   * @param {number} params.leadId - Lead ID (optional)
   * @param {boolean} params.isMediaId - True if videoUrl is media ID
   * @returns {Promise<Object>} Sent message record
   */
  static async sendVideoMessage({
    lineId,
    phoneNumber,
    videoUrl,
    uploadUrl,
    caption,
    userId,
    leadId,
    isMediaId = false
  }) {
    try {
      // Get WhatsApp line with credentials
      const line = await WhatsAppLine.findByPk(lineId);

      if (!line) {
        throw new AppError('WhatsApp line not found', 404);
      }

      if (!line.is_active) {
        throw new AppError('WhatsApp line is not active', 400);
      }

      // Create WhatsApp API client
      const apiClient = new WhatsAppApiClient({
        phoneNumberId: line.phone_number_id,
        accessToken: line.access_token,
        businessAccountId: line.business_account_id
      });

      // Send video via WhatsApp API
      const apiResponse = await apiClient.sendVideoMessage(
        phoneNumber,
        videoUrl,
        { caption, isMediaId }
      );

      // Get or create lead
      let lead = leadId ? await Lead.findByPk(leadId) : null;

      if (!lead) {
        lead = await Lead.findOne({ where: { phone_number: phoneNumber } });
      }

      // Save message to database
      const message = await Message.create({
        line_id: lineId,
        lead_id: lead?.id || null,
        user_id: userId,
        phone_number: phoneNumber,
        message_content: caption || '[Video]',
        message_type: 'video',
        direction: 'outgoing',
        status: 'sent',
        file_url: uploadUrl,
        meta_message_id: apiResponse.messageId,
        created_at: new Date()
      });

      // Load relations for socket broadcast
      const messageWithRelations = await Message.findByPk(message.id, {
        include: [
          { model: Lead, as: 'lead' },
          { model: User, as: 'sender', attributes: ['id', 'name', 'email'] }
        ]
      });

      // Emit message:sent event via Socket.io
      SocketService.emitToLine(lineId, 'message:sent', {
        message: messageWithRelations,
        conversationId: `${phoneNumber}_${lineId}`
      });

      return messageWithRelations;
    } catch (error) {
      console.error('Error sending video message:', error);

      // If API error, save failed message to DB
      if (error.statusCode && error.statusCode >= 400) {
        await Message.create({
          line_id: lineId,
          lead_id: leadId || null,
          user_id: userId,
          phone_number: phoneNumber,
          message_content: caption || '[Video]',
          message_type: 'video',
          direction: 'outgoing',
          status: 'failed',
          file_url: uploadUrl,
          created_at: new Date()
        });
      }

      throw error;
    }
  }

  /**
   * Update message status
   *
   * @param {string} metaMessageId - Meta's message ID
   * @param {string} status - New status (delivered, read, failed)
   * @returns {Promise<Object>} Updated message
   */
  static async updateMessageStatus(metaMessageId, status) {
    try {
      const message = await Message.findOne({
        where: { meta_message_id: metaMessageId }
      });

      if (!message) {
        console.warn(`Message not found for meta_message_id: ${metaMessageId}`);
        return null;
      }

      // Update status
      message.status = status;
      await message.save();

      // Load relations
      const messageWithRelations = await Message.findByPk(message.id, {
        include: [
          { model: Lead, as: 'lead' },
          { model: User, as: 'sender', attributes: ['id', 'name', 'email'] }
        ]
      });

      // Emit message:status event via Socket.io
      SocketService.emitToLine(message.line_id, 'message:status', {
        messageId: message.id,
        metaMessageId,
        status,
        conversationId: `${message.phone_number}_${message.line_id}`
      });

      return messageWithRelations;
    } catch (error) {
      console.error('Error updating message status:', error);
      throw error;
    }
  }

  /**
   * Send interactive message (buttons or list)
   *
   * @param {Object} params - Message parameters
   * @param {number} params.lineId - WhatsApp line ID
   * @param {string} params.phoneNumber - Recipient phone number (E.164)
   * @param {Object} params.interactiveData - Interactive message data (WhatsApp API format)
   * @param {number} params.userId - Sending user ID
   * @param {number} params.leadId - Lead ID (optional)
   * @returns {Promise<Object>} Sent message record
   */
  static async sendInteractiveMessage({ lineId, phoneNumber, interactiveData, userId, leadId }) {
    try {
      // Get WhatsApp line with credentials
      const line = await WhatsAppLine.findByPk(lineId);

      if (!line) {
        throw new AppError('WhatsApp line not found', 404);
      }

      if (!line.is_active) {
        throw new AppError('WhatsApp line is not active', 400);
      }

      // Create WhatsApp API client
      const apiClient = new WhatsAppApiClient({
        phoneNumberId: line.phone_number_id,
        accessToken: line.access_token,
        businessAccountId: line.business_account_id
      });

      // Send interactive message via WhatsApp API
      const apiResponse = await apiClient.sendInteractiveMessage(
        phoneNumber,
        interactiveData
      );

      // Get or create lead
      let lead = leadId ? await Lead.findByPk(leadId) : null;

      if (!lead) {
        lead = await Lead.findOne({ where: { phone_number: phoneNumber } });
      }

      // Extract message content for database storage
      const messageContent = interactiveData.body?.text || '[Interactive Message]';
      const interactiveType = interactiveData.type; // 'button' or 'list'

      // Prepare interactive_data for storage
      const storageData = {
        header: interactiveData.header?.text || null,
        body: interactiveData.body?.text || null,
        footer: interactiveData.footer?.text || null
      };

      if (interactiveType === 'button') {
        storageData.buttons = interactiveData.action?.buttons?.map(btn => ({
          id: btn.reply.id,
          text: btn.reply.title
        })) || [];
      } else if (interactiveType === 'list') {
        storageData.button = interactiveData.action?.button;
        storageData.sections = interactiveData.action?.sections || [];
      }

      // Save message to database
      const message = await Message.create({
        line_id: lineId,
        lead_id: lead?.id || null,
        user_id: userId,
        phone_number: phoneNumber,
        message_content: messageContent,
        message_type: 'interactive',
        interactive_type: interactiveType,
        interactive_data: storageData,
        direction: 'outgoing',
        status: 'sent',
        meta_message_id: apiResponse.messageId,
        created_at: new Date()
      });

      // Load user relation for socket broadcast
      const messageWithRelations = await Message.findByPk(message.id, {
        include: [
          { model: Lead, as: 'lead' },
          { model: User, as: 'sender', attributes: ['id', 'name', 'email'] }
        ]
      });

      // Emit message:sent event via Socket.io
      SocketService.emitToLine(lineId, 'message:sent', {
        message: messageWithRelations,
        conversationId: `${phoneNumber}_${lineId}`
      });

      return messageWithRelations;
    } catch (error) {
      console.error('Error sending interactive message:', error);

      // If API error, save failed message to DB
      if (error.statusCode && error.statusCode >= 400) {
        const messageContent = interactiveData?.body || '[Interactive Message]';
        await Message.create({
          line_id: lineId,
          lead_id: leadId || null,
          user_id: userId,
          phone_number: phoneNumber,
          message_content: messageContent,
          message_type: 'interactive',
          interactive_type: interactiveData?.type,
          interactive_data: interactiveData,
          direction: 'outgoing',
          status: 'failed',
          created_at: new Date()
        });
      }

      throw error;
    }
  }
}

