/**
 * POST /api/v1/messages/send
 *
 * Send text or image message via WhatsApp
 */

import MessageSender from '../../../services/whatsapp/MessageSender.js';
import { messageSendRateLimiter } from '../../../middleware/rateLimiter.js';
import { AppError } from '../../../middleware/errorHandler.js';
import ConversationAssignment from '../../../models/sequelize/ConversationAssignment.js';
import { Op } from 'sequelize';

/**
 * Get phone number variations (with and without + prefix)
 */
function getPhoneVariations(phone) {
  const normalized = phone.replace(/\D/g, '');
  return [`+${normalized}`, normalized];
}

export default async function sendMessage(req, res, next) {
  try {
    const {
      lineId,
      phoneNumber,
      messageContent,
      messageType,
      imageUrl,
      documentUrl,
      audioUrl,
      videoUrl,
      uploadUrl,
      caption,
      filename,
      leadId,
      interactiveData
    } = req.body;
    const userId = req.user.id;

    // Validate required fields
    if (!lineId || !phoneNumber) {
      throw new AppError('lineId and phoneNumber are required', 400);
    }

    // Validate phone number format (E.164)
    const phoneRegex = /^\+?[1-9]\d{1,14}$/;

    if (!phoneRegex.test(phoneNumber)) {
      throw new AppError('Invalid phone number format. Use E.164 format (e.g., +1234567890)', 400);
    }

    // Check if user has access to this line
    if (req.user.role !== 'admin') {
      const hasAccess = req.user.assignedLines?.includes(lineId);

      if (!hasAccess) {
        throw new AppError('You do not have access to this WhatsApp line', 403);
      }
    }

    // CRITICAL: Find existing ConversationAssignment to maintain campaign context
    // This ensures outgoing messages are associated with the same campaign as incoming messages
    const phoneVariations = getPhoneVariations(phoneNumber);
    const conversationAssignment = await ConversationAssignment.findOne({
      where: {
        phone_number: { [Op.in]: phoneVariations },
        line_id: lineId,
      },
      order: [['assigned_at', 'DESC']]  // Get the most recent assignment
    });

    // Extract campaign context from existing assignment
    let campaignId = null;
    let conversationAssignmentId = null;
    let assignedUserIds = null;

    if (conversationAssignment) {
      campaignId = conversationAssignment.campaign_id;
      conversationAssignmentId = conversationAssignment.id;
      assignedUserIds = conversationAssignment.assigned_user_id ? [conversationAssignment.assigned_user_id] : null;
      console.log('[send.js] Found conversation assignment:', {
        campaign_id: campaignId,
        conversation_assignment_id: conversationAssignmentId,
        assigned_user_id: conversationAssignment.assigned_user_id
      });
    } else {
      console.log('[send.js] No conversation assignment found for:', {
        phone_number: phoneNumber,
        line_id: lineId
      });
    }

    let sentMessage;

    // Send based on message type
    if (messageType === 'text') {
      if (!messageContent) {
        throw new AppError('messageContent is required for text messages', 400);
      }

      sentMessage = await MessageSender.sendTextMessage({
        lineId,
        phoneNumber,
        messageContent,
        userId,
        leadId,
        campaignId,
        conversationAssignmentId,
        assignedUserIds
      });
    } else if (messageType === 'image') {
      if (!imageUrl) {
        throw new AppError('imageUrl is required for image messages', 400);
      }

      sentMessage = await MessageSender.sendImageMessage({
        lineId,
        phoneNumber,
        imageUrl,
        uploadUrl,
        caption,
        userId,
        leadId,
        isMediaId: req.body.isMediaId || false,
        campaignId,
        conversationAssignmentId,
        assignedUserIds
      });
    } else if (messageType === 'document') {
      if (!documentUrl) {
        throw new AppError('documentUrl is required for document messages', 400);
      }

      sentMessage = await MessageSender.sendDocumentMessage({
        lineId,
        phoneNumber,
        documentUrl,
        uploadUrl,
        caption,
        filename,
        userId,
        leadId,
        isMediaId: req.body.isMediaId || false,
        campaignId,
        conversationAssignmentId,
        assignedUserIds
      });
    } else if (messageType === 'audio') {
      if (!audioUrl) {
        throw new AppError('audioUrl is required for audio messages', 400);
      }

      sentMessage = await MessageSender.sendAudioMessage({
        lineId,
        phoneNumber,
        audioUrl,
        uploadUrl,
        userId,
        leadId,
        isMediaId: req.body.isMediaId || false,
        campaignId,
        conversationAssignmentId,
        assignedUserIds
      });
    } else if (messageType === 'video') {
      if (!videoUrl) {
        throw new AppError('videoUrl is required for video messages', 400);
      }

      sentMessage = await MessageSender.sendVideoMessage({
        lineId,
        phoneNumber,
        videoUrl,
        uploadUrl,
        caption,
        userId,
        leadId,
        isMediaId: req.body.isMediaId || false,
        campaignId,
        conversationAssignmentId,
        assignedUserIds
      });
    } else if (messageType === 'interactive') {
      if (!interactiveData) {
        throw new AppError('interactiveData is required for interactive messages', 400);
      }

      sentMessage = await MessageSender.sendInteractiveMessage({
        lineId,
        phoneNumber,
        interactiveData,
        userId,
        leadId,
        campaignId,
        conversationAssignmentId,
        assignedUserIds
      });
    } else {
      throw new AppError('Invalid messageType. Must be "text", "image", "document", "audio", "video", or "interactive"', 400);
    }

    res.status(201).json({
      success: true,
      message: 'Message sent successfully',
      data: sentMessage
    });
  } catch (error) {
    next(error);
  }
}

